// Variant A: "Viewer + filmstrip": one big viewer, a filmstrip of takes, a Make panel on the right.
// Cost: price on the button; anchored popover only when the confirm rule fires.
const VA = (() => {
  const confirmPop = () => {
    const c = S.ui.confirm; if (!c) return '';
    return `<div class="pop" style="right:0;top:100%;margin-top:6px;z-index:40"><div class="sm"><b>${c.ev.count} generation${c.ev.count > 1 ? 's' : ''} · ${c.ev.total ? 'about ' + money(c.ev.total) : 'price unavailable'}</b></div>
<ul class="xs mu" style="margin:6px 0 6px 16px;padding:0">${reasonList(c.ev)}</ul>
<div class="xs mu">${c.items.slice(0, 4).map(i => `${i.label} ${i.price == null ? '' : money(i.price)}`).join('<br>')}${c.items.length > 4 ? '<br>…' : ''}</div>
<div class="xs mu" style="margin:6px 0">Largest ${money(c.ev.largest)} · ${money(Math.max(0, CAP - S.spent))} left today. Runs in the background; one billable run each.</div>
<div class="row"><button class="pri sm" data-act="go_confirm">Start ${c.ev.count > 1 ? c.ev.count + ' generations' : 'generation'} · ${money(c.ev.total)}</button><button class="sm ghost" data-act="no_confirm">Cancel</button></div></div>`;
  };
  const strip = (s) => {
    const live = liveTakes(s); const job = jobOf(s); const insp = S.ui.insp || s.sel || (live[live.length - 1] || {}).id;
    const cells = live.map(t => `<div style="width:150px;flex:none"><div class="poster ${t.id === s.sel ? 'sel' : ''}" style="background-image:${posterOf(s, t)};cursor:pointer;${t.id === insp ? 'box-shadow:0 0 0 2px #fff3' : ''}" data-act="ui" data-key="insp" data-val="${t.id}"><span class="tc">Take ${t.n} · ${t.dur || s.dur}s</span>${t.id === s.sel ? `<span class="tl" style="color:#9fd">${s.final ? 'final' : 'selected'}</span>` : ''}</div>
<div class="row xs" style="margin-top:3px"><label class="row mu" style="gap:3px"><input type="checkbox" ${S.ui.compare.includes(t.id) ? 'checked' : ''} data-act="cmp" data-take="${t.id}" data-max="2"> compare</label>${t.late ? '<span class="chip">arrived after cancel</span>' : ''}${t.guidance ? '<span class="dim" title="' + t.guidance + '">guided</span>' : ''}</div></div>`).join('');
    const ghost = job ? `<div style="width:150px;flex:none"><div class="slate" style="flex-direction:column;gap:6px"><span class="xs">Generating… ${Math.min(99, Math.round(job.progress))}%</span><div class="prog" style="width:80%"><i style="width:${job.progress}%"></i></div><button class="sm ghost" data-act="cancel" data-job="${job.id}">Cancel</button></div></div>` : '';
    const partial = s.batchPartial && !job ? `<div style="width:150px;flex:none"><div class="slate" style="flex-direction:column;gap:4px"><span class="xs"><b>${s.batchPartial.done} of ${s.batchPartial.total} parts made</b></span><span class="xs dim">no take until assembled</span><button class="sm" data-act="gen" data-shot="${s.id}">Make part ${s.batchPartial.done + 1} <span class="price">${money(priceOf(s, S.ui.model) / s.long)}</span></button></div></div>` : '';
    const fail = s.failed ? `<div style="width:180px;flex:none"><div class="slate" style="flex-direction:column;gap:5px;padding:6px"><span class="xs" style="color:var(--bad)">${s.failed.reason}</span><span class="xs dim">${s.failed.billed === 'maybe' ? 'You may have been charged.' : 'Not charged.'}</span><button class="sm" data-act="retry" data-shot="${s.id}">Retry <span class="price">${money(priceOf(s, s.failed.model))}</span></button></div></div>` : '';
    return { html: `<div class="row" style="align-items:flex-start;overflow:auto;padding-bottom:6px">${cells}${ghost}${partial}${fail}${!cells && !ghost && !partial && !fail ? '<div class="slate" style="width:240px;flex:none">No takes yet. Make one →</div>' : ''}</div>`, insp };
  };
  function renderShot(s) {
    const i = S.shots.indexOf(s); const prev = S.shots[i - 1], next = S.shots[i + 1];
    const { html, insp } = strip(s); const t = s.takes.find(x => x.id === insp);
    const cmp = S.ui.compare.map(id => s.takes.find(x => x.id === id)).filter(Boolean);
    const viewer = cmp.length === 2
      ? `<div class="row" style="gap:6px">${cmp.map(c => `<div class="grow"><div class="poster ${S.ui.vplay ? 'kb' : ''}" style="background-image:${posterOf(s, c)}"><span class="tc">Take ${c.n}</span></div><div class="row" style="margin-top:4px"><button class="sm" data-act="select" data-shot="${s.id}" data-take="${c.id}">${s.sel === c.id ? '✓ Selected' : 'Select this one'}</button></div></div>`).join('')}</div>`
      : t ? `<div class="poster ${S.ui.vplay ? 'kb' : ''}" style="background-image:${posterOf(s, t)};max-width:600px"><span class="tc">Take ${t.n} · ${t.dur || s.dur}s · ${t.model}</span><button class="sm" style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%)" data-act="ui" data-key="vplay" data-val="">${S.ui.vplay ? '❚❚' : '▶'}</button></div>`
        : `<div class="slate" style="min-height:260px"><div><b>No take to show</b><div class="xs">${s.long ? 'This long shot becomes one Take once all parts are made.' : 'Make the first take on the right.'}</div></div></div>`;
    const acts = t && cmp.length < 2 ? `<div class="row" style="margin-top:8px;flex-wrap:wrap">
      ${s.sel === t.id ? `<span class="chip ok">Selected</span><button class="sm" data-act="deselect" data-shot="${s.id}">Unselect</button><button class="sm" data-act="final" data-shot="${s.id}">${s.final ? '🔒 Final · unlock' : 'Mark final (optional)'}</button>` : `<button class="pri" data-act="select" data-shot="${s.id}" data-take="${t.id}">Select this take</button>${s.sel ? '<span class="xs mu">replaces the current pick; nothing is lost</span>' : ''}`}
      <button class="sm" data-act="reject" data-shot="${s.id}" data-take="${t.id}">Reject</button>
      <button class="sm ghost" data-act="playctx" data-shot="${s.id}" data-take="${t.id}">▶ Play in context</button></div>
      <div class="xs mu" style="margin-top:4px">${t.late ? 'Arrived after you cancelled. Attached, not selected. ' : ''}${t.guidance ? 'Guidance: “' + t.guidance + '”. ' : ''}Switching the pick flags only what was built from the old one, quietly.</div>` : '';
    const ctxItems = S.play.items;
    const ctx = `<div class="row" style="margin-top:10px;gap:6px;align-items:stretch"><div style="width:23%"><div class="xs mu">Before · ${prev ? prev.label : '—'}</div>${prev ? (prev.sel ? `<div class="poster" style="background-image:${posterOf(prev, selTake(prev))};cursor:pointer" data-act="go" data-view="shot" data-shot="${prev.id}"></div>` : '<div class="slate xs">no take</div>') : ''}</div><div style="width:23%"><div class="xs mu">This shot</div><div class="poster sel" style="background-image:${t ? posterOf(s, t) : 'none'}"></div></div><div style="width:23%"><div class="xs mu">After · ${next ? next.label : '—'}</div>${next ? (next.sel ? `<div class="poster" style="background-image:${posterOf(next, selTake(next))};cursor:pointer" data-act="go" data-view="shot" data-shot="${next.id}"></div>` : '<div class="slate xs">no take</div>') : ''}</div><div class="grow xs mu" style="padding-left:6px">${ctxItems ? `<div class="poster kb" style="background-image:${posterOf(ctxItems[Math.max(0, currentIndex(playItems()))].shot, ctxItems[Math.max(0, currentIndex(playItems()))].take)}"></div><button class="sm" data-act="endctx">Stop</button>` : 'Inspect in context: plays the previous shot, this take, the next shot.'}</div></div>`;
    const rej = rejTakes(s);
    const rejHtml = rej.length ? `<div class="xs mu" style="margin-top:8px">Rejected (${rej.length}): ${rej.map(r => `Take ${r.n} <button class="sm ghost" data-act="restore" data-shot="${s.id}" data-take="${r.id}">restore</button>`).join(' · ')}</div>` : '';
    const p = priceOf(s, S.ui.model); const generating = jobOf(s);
    const make = `<div class="col" style="position:relative;background:var(--p1);border:1px solid var(--ln);border-radius:8px;padding:12px">
      <b>${s.takes.length ? 'Make another take' : 'Make a take'}</b>
      <div class="xs mu">Model</div>${modelSelect()}
      <div class="xs mu">Guidance <span class="dim">(optional)</span></div>${guidanceBox()}
      <div style="position:relative"><button class="pri" style="width:100%;padding:8px" data-act="gen" data-shot="${s.id}" ${generating ? 'disabled' : ''}>${generating ? 'Generating…' : s.takes.length ? 'Regenerate' : 'Generate'} · ${p == null ? 'price unavailable' : money(p)}${s.long ? ' · ' + s.long + ' parts' : ''}</button>${S.ui.confirm && S.ui.confirm.items.length === 1 ? confirmPop() : ''}</div>
      <div class="xs mu">${p != null && p < 2 ? 'One click starts it. Runs in the background.' : p == null ? 'Unknown price asks you to confirm first.' : 'This one is $2.00 or more, so you confirm first.'}</div>
      <button class="ghost sm" data-act="ui" data-key="inspect" data-val="">${S.ui.inspect ? '▾' : '▸'} Prompt and references</button>${S.ui.inspect ? inspectBlock(s) : ''}</div>`;
    const miss = sceneMissingItems(S.ui.model);
    const sceneBar = `<div class="row" style="padding:8px 16px;border-bottom:1px solid var(--ln);position:relative"><span class="mu xs">SCENE 7</span><span class="chip">${sceneStats().sel} of ${sceneStats().n} selected</span>${sceneStats().gap ? `<span class="chip">${S.shots.filter(x => !x.sel && !liveTakes(x).length).length} with no take</span>` : ''}<span class="grow"></span>
      <div style="position:relative"><button class="sm" data-act="genScene" ${miss.length ? '' : 'disabled'}>Generate ${miss.length} missing · <span class="price">${money(miss.reduce((a, x) => a + (x.price || 0), 0))}</span></button>${S.ui.confirm && S.ui.confirm.items.length > 1 ? confirmPop() : ''}</div>
      <button class="sm" data-act="genFilm">Whole film…</button><button class="sm" data-act="go" data-view="review" data-scope="scene">▶ Play scene</button></div>`;
    return `${sceneBar}<div style="padding:14px 16px"><div class="row"><button class="ghost sm" ${prev ? `data-act="go" data-view="shot" data-shot="${prev.id}" data-keep="1"` : 'disabled'}>◀</button><div class="grow"><div class="row"><b style="font-size:15px">${s.label} · ${s.title}</b>${oodDot(s)}${stateChip(s)}</div><div class="mu xs">${s.plan} · ${s.dur}s planned</div>${oodPop(s)}</div>${S.returnTo ? '<button class="sm" data-act="back">↩ Back to review</button>' : ''}<button class="ghost sm" ${next ? `data-act="go" data-view="shot" data-shot="${next.id}" data-keep="1"` : 'disabled'}>▶</button></div>
      <div style="display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px;margin-top:12px"><div>${viewer}${acts}<div style="margin-top:12px" class="xs mu">TAKES</div>${html}${rejHtml}${ctx}</div><div>${make}</div></div></div>`;
  }
  function renderReview() {
    const it = playItems(); const tot = totalDur() || 1; const ci = currentIndex(it); const cu = it[ci];
    const scene = S.scope === 'scene';
    const block = (x, w) => { const s = x.shot; const stt = s.mock ? (s.sel ? 'selected' : 'missing') : state(s); const bg = x.gap ? '' : `background-image:${s.mock ? poster(s.hue, s.id) : posterOf(s, x.take)};background-size:cover;`; return `<div title="${s.label}" data-act="seek" data-t="${x.start}" style="width:${w ? w + 'px' : (x.d / tot * 100).toFixed(2) + '%'};${w ? 'flex:none;' : ''}height:${scene ? 54 : 22}px;${bg}border-radius:3px;position:relative;cursor:pointer;${x.gap ? '' : ''}${ci >= 0 && it[ci] === x ? 'outline:2px solid #fff;z-index:2;' : ''}" class="${x.gap ? 'hatch' : ''}">${scene ? `<span class="tc" style="position:absolute;left:3px;bottom:2px;font-size:10px;background:#000a;padding:0 3px;border-radius:3px">${s.label}</span>` : ''}${s.ood && !s.ood.kept ? '<span class="wd" style="position:absolute;right:3px;top:3px;margin:0"></span>' : ''}${stt === 'failed' ? '<span class="chip bad" style="position:absolute;left:3px;top:2px;padding:0 4px">!</span>' : ''}</div>`; };
    const head = `<div class="tabs"><button class="${scene ? 'on' : ''}" data-act="go" data-view="review" data-scope="scene">Scene 7</button><button class="${!scene ? 'on' : ''}" data-act="go" data-view="review" data-scope="film">Whole film</button><span class="grow"></span><label class="row mu xs"><input type="checkbox" ${S.play.skipGaps ? 'checked' : ''} data-act="skipgaps"> skip gaps</label></div>`;
    const stage = `<div style="max-width:720px">${stageHTML(cu, `<span class="tl">${tc(S.play.t)} / ${tc(tot)}</span>`)}<div class="row" style="margin-top:6px"><button data-act="nextitem" data-dir="-1">⏮</button><button class="pri" data-act="play">${S.play.on ? '❚❚ Pause' : '▶ Play'}</button><button data-act="nextitem" data-dir="1">⏭</button><span class="mu xs">${cu ? cu.shot.label + (cu.gap ? ' · no selected take (gap)' : '') : ''}</span><span class="grow"></span>${cu && !cu.shot.mock ? `<button data-act="go" data-view="shot" data-shot="${cu.shot.id}" data-ret="1">Fix this shot ↗</button>` : ''}</div></div>`;
    let track;
    if (scene) track = `<div class="row" style="gap:2px;margin-top:12px;position:relative">${it.map(x => block(x)).join('')}<div style="position:absolute;top:-4px;bottom:-4px;width:2px;background:#fff;left:${(S.play.t / tot * 100).toFixed(2)}%"></div></div>`;
    else {
      const byScene = {}; it.forEach(x => { const k = x.shot.scene || 7; (byScene[k] = byScene[k] || []).push(x); });
      track = `<div class="col" style="gap:3px;margin-top:12px">${Object.keys(byScene).map(k => { const row = byScene[k]; const sm = row.reduce((a, x) => a + x.d, 0); return `<div class="row"><span class="xs mu" style="width:56px">Scene ${k}</span><div class="row" style="gap:1px;flex:1">${row.map(x => block(x, Math.max(8, x.d * 4))).join('')}</div><span class="xs dim" style="width:90px">${row.filter(x => !x.gap).length}/${row.length} selected</span></div>`; }).join('')}</div>`;
    }
    const issues = [];
    S.shots.forEach(s => { const stt = state(s); if (stt === 'missing') issues.push([s, 'No take yet', `Generate <span class="price">${money(priceOf(s, S.ui.model))}</span>`, 'gen']); if (stt === 'needs-pick') issues.push([s, 'Takes exist, none picked', 'Review takes', 'go']); if (stt === 'failed') issues.push([s, 'Failed · may have been charged', `Retry <span class="price">${money(priceOf(s, 'pro'))}</span>`, 'retry']); if (s.ood && !s.ood.kept) issues.push([s, 'Possibly out of date: ' + s.ood.reason, 'Review', 'go']); if (stt === 'generating') issues.push([s, 'Still generating', 'Open', 'go']); });
    const list = `<div class="col" style="margin-top:16px"><div class="xs mu">WHAT'S MISSING OR UNSETTLED (${issues.length}) · none of it blocks playback or export</div>${issues.map(([s, why, lbl, act]) => `<div class="row" style="padding:5px 8px;background:var(--p1);border-radius:6px"><b>${s.label}</b><span class="grow mu">${why}</span><button class="sm" data-act="${act}" data-shot="${s.id}" data-view="shot" data-ret="1">${lbl}</button></div>`).join('')}${S.ui.confirm ? '<div style="position:relative;height:0">' + confirmPop() + '</div>' : ''}</div>`;
    return `${head}<div style="padding:14px 16px">${scene ? '' : '<div class="note" style="margin-bottom:10px">Film view: 22 scenes. Scene 7 is live; other scenes are mock data. Playback of the whole film walks the same selected takes.</div>'}${stage}${track}${list}</div>`;
  }
  return { renderShot, renderReview };
})();
